#include <bits/stdc++.h>
using namespace std;

const int INF = numeric_limits<int>::max();

namespace mcmf {

const int MAX_NODES = 10001;
struct Edge { int to, rev; int cap, cost; };
vector<Edge> adj[MAX_NODES];
int visited[MAX_NODES], cur[MAX_NODES], node_count;
int dist[MAX_NODES], potential[MAX_NODES];

int create_node() {
    adj[node_count++].clear();
    return node_count - 1;
}

void add_edge(int u, int v, int cap, int cost) {
    adj[u].emplace_back(Edge{v, (int)adj[v].size(), cap, cost});
    adj[v].emplace_back(Edge{u, (int)adj[u].size() - 1, 0, -cost});
}

bool dijkstra(int source, int sink) {
    fill(dist, dist + node_count, INF);
    fill(visited, visited + node_count, 0);
    using P = pair<int, int>;
    priority_queue<P, vector<P>, greater<P>> pq;
    pq.emplace(dist[source] = 0, source);
    while (!pq.empty()) {
        auto [du, u] = pq.top(); pq.pop();
        if (visited[u]) continue;
        visited[u] = true;
        for (auto& e : adj[u]) {
            int v = e.to;
            int dv = du + potential[u] + e.cost - potential[v];
            if (e.cap == 0 || visited[v] || dist[v] <= dv) continue;
            pq.emplace(dist[v] = dv, v);
        }
    }
    return visited[sink];
}

bool dinic_bfs(int source, int sink) {
    fill(visited, visited + node_count, 0);
    queue<int> q;
    q.push(source);
    visited[source] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (auto& e : adj[u]) {
            int v = e.to;
            if (visited[v] || e.cap == 0) continue;
            if (dist[v] != dist[u] + e.cost - potential[v] + potential[u]) continue;
            visited[v] = visited[u] + 1;
            q.push(v);
        }
    }
    return visited[sink] != 0;
}

int dinic_dfs(int u, int sink, int flow) {
    if (u == sink) return flow;
    int pushed = 0;
    for (int& i = cur[u]; i < (int)adj[u].size(); ++i) {
        auto& e = adj[u][i];
        int v = e.to;
        if (e.cap == 0 || visited[v] != visited[u] + 1) continue;
        if (dist[v] != dist[u] + e.cost - potential[v] + potential[u]) continue;
        int df = dinic_dfs(v, sink, min(e.cap, flow));
        pushed += df;
        flow -= df;
        e.cap -= df;
        adj[v][e.rev].cap += df;
        if (flow == 0) break;
    }
    return pushed;
}

pair<int, int> min_cost_max_flow(int source, int sink, int max_flow_limit) {
    int total_flow = 0, total_cost = 0;
    fill(potential, potential + node_count, 0);
    while (dijkstra(source, sink)) {
        int flow = 0;
        while (dinic_bfs(source, sink)) {
            fill(cur, cur + node_count, 0);
            int df = dinic_dfs(source, sink, max_flow_limit);
            max_flow_limit -= df;
            flow += df;
            if (max_flow_limit == 0) break;
        }
        total_flow += flow;
        total_cost += (dist[sink] + potential[sink]) * flow;
        for (int i = 0; i < node_count; ++i)
            potential[i] += dist[i];
        if (max_flow_limit == 0) break;
    }
    return {total_flow, total_cost};
}

}

int main() {
    int n, m, k, c, d;
    scanf("%d %d %d %d %d", &n, &m, &k, &c, &d);
    int layers = max(n, k) * 2;
    mcmf::create_node();
    int s = mcmf::create_node();
    int t = mcmf::create_node();
    for (int j = 0; j < k; ++j) {
        int a;
        scanf("%d", &a);
        --a;
        mcmf::add_edge(s, a, 1, 0);
    }
    for (int z = 1; z <= m; ++z) {
        int u, v;
        scanf("%d %d", &u, &v);
        --u; --v;
        for (int i = 0; i + 1 < layers; ++i) {
            int u1 = u + i * n, v1 = v + (i + 1) * n;
            int u2 = u + (i + 1) * n, v2 = v + i * n;
            for (int j = 0; j < k; ++j) {
                mcmf::add_edge(u1, v1, 1, c + d * (2 * j + 1));
                mcmf::add_edge(v2, u2, 1, c + d * (2 * j + 1));
            }
        }
    }
    for (int i = 0; i + 1 < layers; ++i) {
        for (int j = 0; j < n; ++j) {
            int u = j + i * n, v = j + (i + 1) * n;
            mcmf::add_edge(u, v, INF, c);
        }
    }
    for (int i = 0; i < layers; ++i)
        mcmf::add_edge(i * n, t, INF, 0);
    printf("%d\n", mcmf::min_cost_max_flow(s, t, INF).second);
    return 0;
}
